#include "sshconfigeditor.h"

#include "ui_sshconfigeditor.h"   // generated by uic from sshconfigeditor.ui

SshConfigEditor::SshConfigEditor(QWidget *parent) : iwp::FormConfigEditor(parent)
{
    // The layout, labels, ranges and defaults are in sshconfigeditor.ui; here only the keys of the
    // config are bound to the widgets.
    auto *page = new QWidget;
    Ui::SshConfigEditor ui;
    ui.setupUi(page);
    setupPage(page);

    bindText(QStringLiteral("host"), ui.hostEdit);
    bindInt(QStringLiteral("port"), ui.portSpin);
    bindText(QStringLiteral("user"), ui.userEdit);
    bindFile(QStringLiteral("identityFile"), ui.identityEdit, ui.identityBrowse, tr("Identity file"));
    bindText(QStringLiteral("jumpHost"), ui.jumpHostEdit);
    // same order as the items in the .ui
    bindComboValues(QStringLiteral("hostKeyChecking"), ui.hostKeyCombo,
                    {QString(), QStringLiteral("ask"), QStringLiteral("accept-new")});
    bindInt(QStringLiteral("connectTimeout"), ui.timeoutSpin);
    bindText(QStringLiteral("sshPath"), ui.sshPathEdit);
}

QString SshConfigEditor::validate() const
{
    return config().value(QStringLiteral("host")).toString().isEmpty()
               ? tr("Enter the host name or address") : QString();
}
